/** Generated by scaffold-crud-pages. Query hooks for VoAssets.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchVoAssetsList,
  fetchVoAssetsById,
  createVoAssets,
  updateVoAssets,
  deleteVoAssets,
  type FetchVoAssetsListParams,
} from '~/services/httpServices/voAssetsService';
import type { CreateVoAssetsRequest, UpdateVoAssetsRequest } from '~/types/vo-assets';

const DOMAIN = 'voAssets';

export function useVoAssetsList(params?: FetchVoAssetsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchVoAssetsList(params),
  });
}

export function useVoAssets(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchVoAssetsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateVoAssets() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateVoAssetsRequest) => createVoAssets(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateVoAssets() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateVoAssetsRequest }) =>
      updateVoAssets(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteVoAssets() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteVoAssets(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
